(2018, 12, 103, 210, 'در هر جمع یا اجتماعی به دنبال دریافت توجه و تحسین دیگران هستم.', 0, NULL, 210),
(2019, 12, 103, 211, 'برای اینکه احساس کنم آدم ارزشمندی هستم نیازمند تأیید، تحسین و تمجید زیاد دیگران هستم.', 0, NULL, 211),
(2020, 12, 104, 212, 'حتی زمانی که کارها خوب پیش می رود، احساس می کنم که این حس خوب موقتی است.', 0, NULL, 212),
(2021, 12, 104, 213, 'وقتی اتفاقات خوبی در زندگی ام می افتد، نگرانم که مبادا بدشانسی از راه برسد.', 0, NULL, 213),
(2022, 12, 104, 214, 'خیلی نمی توانم در کارها دقت کنم چون تقریباً همیشه کارها غلط از آب درمی آیند.', 0, NULL, 214),
(2023, 12, 104, 215, 'مهم نیست که چقدر سختکوش باشم، نگرانم که تمام سرمایه مالی ام را بر باد فنا بدهم.', 0, NULL, 215),
(2024, 12, 104, 216, 'نگرانم که مبادا یک تصمیم اشتباه به فاجعه ای تمام عیار منجر شود.', 0, NULL, 216),
(2025, 12, 104, 217, 'اغلب درباره تصمیم های کوچک نیز وسواس نشان می دهم به این دلیل که معتقدم پیامدهای یک تصمیم گیری اشتباه می تواند خیلی ناگوار باشد.', 0, NULL, 217),
(2026, 12, 104, 218, 'معتقدم اگر با این فرض کارم را شروع کنم که شکست می خورم، احساس بهتری دارم زیرا اگر شکست بخورم احساس ناامیدی نمی کنم.', 0, NULL, 218),
(2027, 12, 104, 219, 'بیشتر ذهنم درگیر وقایع منفی زندگی است تا وقایع مثبت.', 0, NULL, 219),
(2028, 12, 104, 220, 'اغلب بدبین هستم.', 0, NULL, 220),
(2029, 12, 104, 221, 'افراد صمیمی زندگی ام مرا آدم نگرانی می دانند.', 0, NULL, 221),
(2030, 12, 104, 222, 'اگر دیگران سخت مجذوب برخی از کارهای من شوند، احساس ناخوشایندی به من دست می دهد و حس می کنم که این تعریف و تمجیدها، هشداری است برای اینکه قرار است عاقبت کار بد تمام شود یا به مشکل بخورد.', 0, NULL, 222),
(2031, 12, 105, 223, 'اگر اشتباه کنم باید تنبیه شوم.', 0, NULL, 223),
(2032, 12, 105, 224, 'معتقدم اگر سنگ تمام نگذارم بدون شک شکست می خورم.', 0, NULL, 224),
(2033, 12, 105, 225, 'اگر اشتباه کنم هیچ عذر و بهانه ای پذیرفته نیست.', 0, NULL, 225),
(2034, 12, 105, 226, 'افراد مسئولیت گریز باید به نحوی گوشمالی داده شوند.', 0, NULL, 226),
(2035, 12, 105, 227, 'بیشتر اوقات عذر و بهانه های دیگران را نمی پذیرم، زیرا معتقدم لازم است آدمها مسئولیت کارهای خودشان را بپذیرند و عواقب کارهایشان را ببینند.', 0, NULL, 227),
(2036, 12, 105, 228, 'اگر کارم را درست انجام ندهم باید عواقبش را بپذیرم.', 0, NULL, 228),
(2037, 12, 105, 229, 'اغلب به اشتباهات خود فکر می کنم و از دست خودم عصبانی می شوم.', 0, NULL, 229),
(2038, 12, 105, 230, 'وقتی دیگران مرتکب اشتباهی می شوند، پذیرش این جمله برای من سخت است: «ببخش و فراموش کن».', 0, NULL, 230),
(2039, 12, 105, 231, 'حتی بعد از اینکه کسی از من معذرت خواهی می کند، باز هم دست از لجاجت و کینه جویی برنمی دارم.', 0, NULL, 231),
(2040, 12, 105, 232, 'حس می کنم من آدم بدی هستم که لایق تنبیه است.', 0, NULL, 232);
