(9, 9, 8, 11, '2.0', 138.00, '[{\"id\":86,\"code\":\"attachment_anxiety\",\"title\":\"اضطراب دلبستگی (Attachment Anxiety)\",\"description\":\"ترس از رهاشدگی، طرد، نیاز مداوم به تأیید و دلواپسی از دست دادن رابطه\",\"min_score\":18,\"max_score\":126,\"color_hex\":\"#E74C3C\",\"raw_score\":89,\"item_count\":18,\"average_score\":4.94000000000000039079850466805510222911834716796875,\"category_name\":\"اضطراب دلبستگی بالا (ناایمن)\",\"severity_level\":\"severe\",\"interpretation\":\"اشتغال ذهنی شدید با رابطه، ترس از طرد و نیاز مداوم به دلگرمی و تأیید طرف مقابل.\"},{\"id\":87,\"code\":\"attachment_avoidance\",\"title\":\"اجتناب دلبستگی (Attachment Avoidance)\",\"description\":\"ترس از صمیمیت عمیق، فاصله گزینی هیجانی و اتکای افراطی به خودکفایی\",\"min_score\":18,\"max_score\":126,\"color_hex\":\"#3498DB\",\"raw_score\":49,\"item_count\":18,\"average_score\":2.720000000000000195399252334027551114559173583984375,\"category_name\":\"اجتناب دلبستگی پایین (راحت با صمیمیت)\",\"severity_level\":\"normal\",\"interpretation\":\"راحتی با نزدیکی عاطفی، ابراز آزادانه احساسات و اعتماد به شریک عاطفی.\"}]', 'پروفایل سبک دلبستگی', 'normal', 'نمرات شما در دو بعد اضطراب و اجتناب مشخص‌کننده یکی از ۴ سبک اصلی دلبستگی (ایمن، مضطرب، اجتنابی-هراسناک، اجتنابی-طعنه‌زن) است.', '[{\"question_number\":1,\"question_text\":\"من نگرانم که مبادا شریک عاطفی‌ام مرا به اندازه من دوست نداشته باشد.\",\"selected_option_number\":7,\"selected_option_text\":\"کاملاً موافقم (۷)\",\"option_raw_score\":7,\"is_reverse_scored\":false,\"item_final_score\":7,\"dimension_id\":86,\"dimension_title\":\"اضطراب دلبستگی (Attachment Anxiety)\"},{\"question_number\":2,\"question_text\":\"غالباً نگرانم که شریک زندگی‌ام مرا ترک کند یا از رابطه با من دلسرد شود.\",\"selected_option_number\":7,\"selected_option_text\":\"کاملاً موافقم (۷)\",\"option_raw_score\":7,\"is_reverse_scored\":false,\"item_final_score\":7,\"dimension_id\":86,\"dimension_title\":\"اضطراب دلبستگی (Attachment Anxiety)\"},{\"question_number\":3,\"question_text\":\